package com.pridesys.ticketing.issue.service.impl;
import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import com.pridesys.ticketing.issue.service.IIssueService; import com.pridesys.ticketing.repository.*; import org.springframework.data.domain.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class IssueServiceImpl implements IIssueService { private final IssueRepository issues; private final IssueAuditRepository audits; private final ProjectRepository projects; public IssueServiceImpl(IssueRepository i,IssueAuditRepository a,ProjectRepository p){issues=i;audits=a;projects=p;} public PageResponse<IssueResponseDto> list(UserEntity a,long project,String q,int page,int size){scope(a,project);var p=PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100));var r=q==null||q.isBlank()?issues.findByProjectId(project,p):issues.findByProjectIdAndTitleContainingIgnoreCase(project,q,p);return PageResponse.of(r.map(this::map));} public IssueResponseDto get(UserEntity a,long id){var i=issues.findById(id).orElseThrow();scope(a,i.getProjectId());return map(i);} @Transactional public IssueResponseDto create(UserEntity a,CreateIssueRequest r){scope(a,r.projectId());var i=issues.save(new IssueEntity(r.title().trim(),r.description(),r.type(),r.priority(),r.projectId(),r.moduleId(),a.getId()));var saved=issues.save(i);audits.save(new IssueAuditEntity(saved.getId(),a.getId(),"CREATED",null,null,null));return map(saved);} @Transactional public IssueResponseDto update(UserEntity a,long id,UpdateIssueRequest r){var i=issues.findById(id).orElseThrow();scope(a,i.getProjectId());if(a.getRole()==UserRole.CLIENT_USER&&i.getReporterId()!=a.getId())throw new AccessDeniedException("Only the reporter may edit this issue"); audit(i,a,"title",i.getTitle(),r.title());i.setTitle(r.title().trim());i.setDescription(r.description());i.setType(r.type());i.setPriority(r.priority());return map(issues.save(i));} @Transactional public IssueResponseDto move(UserEntity a,long id,IssueStage stage){var i=issues.findById(id).orElseThrow();scope(a,i.getProjectId());if(a.getRole()==UserRole.CLIENT_USER&&(i.getReporterId()!=a.getId()||!(stage==IssueStage.DECLINED||stage==IssueStage.RESOLVED)||i.getStage()!=IssueStage.SUBMITTED))throw new AccessDeniedException("Issue stage transition denied");IssueStage old=i.getStage();i.setStage(stage);audit(i,a,"stage",old.name(),stage.name());return map(issues.save(i));} public List<IssueAuditResponseDto> audit(UserEntity a,long id){var i=issues.findById(id).orElseThrow();scope(a,i.getProjectId());return audits.findByIssueIdOrderByCreatedAtAsc(id).stream().map(x->new IssueAuditResponseDto(x.getId(),x.getIssueId(),x.getActorId(),x.getAction(),x.getFieldName(),x.getOldValue(),x.getNewValue(),x.getCreatedAt())).toList();} private void audit(IssueEntity i,UserEntity a,String field,String oldV,String newV){audits.save(new IssueAuditEntity(i.getId(),a.getId(),"UPDATED",field,oldV,newV));} private void scope(UserEntity a,long project){if(a.getRole()==UserRole.APP_ADMIN||projects.member(project,a.getId()))return;throw new AccessDeniedException("Project access denied");} private IssueResponseDto map(IssueEntity i){return new IssueResponseDto(i.getId(),i.getTitle(),i.getDescription(),i.getType(),i.getPriority(),i.getStage(),i.getVerificationStatus(),i.getProjectId(),i.getModuleId(),i.getReporterId(),i.getCreatedAt(),i.getUpdatedAt());} }
